\begin{defish}
\emph{Zermelo's \citeyear{Zermelo1908Untersuchungen} Axiom of
Infinity.} There is a set $A$ such that $\emptyset \in A$ and
$(\forall x \in A)\{x\} \in A$. 
\end{defish}

target:
\begin{defish}
\emph{د زرمېلو د \citeyear{Zermelo1908Untersuchungen} د نامتناهيت
بديهي اصل.} يو سټ $A$ شته چې $\emptyset \in A$ او
$(\forall x \in A)\{x\} \in A$ وي.
\end{defish}

